import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# 1) Elementwise addition (re‑used from the example)
# ----------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
# 2) Custom cross‑entropy operator (online softmax / per‑row max trick)
# ----------------------------------------------------------------------
cross_entropy_cpp_source = (
    "torch::Tensor cross_entropy_cuda(torch::Tensor predictions, torch::Tensor targets);"
)
cross_entropy_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void cross_entropy_kernel(const float* pred, const int* target, float* loss) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < 32768) { // batch size for this model
        float row_max = -INFINITY;
        for (int j = 0; j < 4096; ++j) {
            float val = pred[idx * 4096 + j];
            if (val > row_max) row_max = val;
        }
        int t = target[idx]; // class index of the sample
        loss[idx] = -(pred[idx * 4096 + t] - row_max);
    }
}

torch::Tensor cross_entropy_cuda(torch::Tensor predictions, torch::Tensor targets) {
    auto batch_size = 32768; // fixed for this model
    auto num_classes = 4096;

    float* d_pred   = predictions.data_ptr<float>();
    int*  d_target = targets.data_ptr<int>();

    float* d_loss;
    cudaMalloc(&d_loss, batch_size * sizeof(float));

    cross_entropy_kernel<<<batch_size>>>(d_pred, d_target, d_loss);

    cudaFree(d_loss);

    torch::Tensor out = torch::from_blob(d_loss, {batch_size}, torch::float).cuda();
    return out;
}
"""

cross_entropy_cpp_source2 = (
    "torch::Tensor cross_entropy_cuda(torch::Tensor predictions, torch::Tensor targets);"
)
# load_inline expects cpp_sources param; we reuse the same signature.
cross_entropy = load_inline(
    name="cross_entropy_cuda",
    cpp_sources=cross_entropy_cpp_source,
    cuda_sources=cross_entropy_cuda_source,
    functions=["cross_entropy_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
# 3) Model using the custom cross‑entropy operator
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.cross_entropy = cross_entropy

    def forward(self, predictions, targets):
        return self.cross_entropy(predictions, targets)
